    /** Record the sheet's terms in days from a date (null: the sheet's today), starting the sheet if it has never
     *  been loaded. */
    @Transactional
    public Sheet setTerms(String id, String user, int terms, LocalDate from) {
        return record(id, user, Sheet.TERMS, from, String.valueOf(terms), false);
    }

    /** Record a grade's own terms in days (null: the sheet's terms) from a date (null: the sheet's today), starting
     *  the sheet if it has never been loaded. */
    @Transactional
    public Sheet setGradeTerms(String id, String user, String grade, Integer terms, LocalDate from) {
        return record(id, user, Sheet.TERMS + "-" + grade, from, terms == null ? null : String.valueOf(terms), false);
    }

    /** Record the sheet's late percent from a date (null: the sheet's today), starting the sheet if it has never
     *  been loaded. */
    @Transactional
    public Sheet setLatePct(String id, String user, BigDecimal latePct, LocalDate from) {
        return record(id, user, Sheet.LATE_PCT, from, scaled(latePct), true);
    }

    /** Set the sheet's policy date (null: the sheet's today), starting the sheet if it has never been loaded. */
    @Transactional
    public Sheet setPolicyDate(String id, String user, LocalDate policyDate) {
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        Rollup.Figures before = rollup.of(id);
        sheet.setPolicyDate(policyDate);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordChangeOnCommit(id, user, "SETTING_CHANGED sheet=" + id + " by=" + user
                + " key=policy-date value=" + (policyDate == null ? "" : policyDate));
        rollup.recordChanges(id, user, before);
        return saved;
    }

    /** Set the sheet's period numbering from (null: off), starting the sheet if it has never been loaded. */
    @Transactional
    public Sheet setPeriodNumberingFrom(String id, String user, LocalDate from) {
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        sheet.setPeriodNumberingFrom(from);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordChangeOnCommit(id, user, "SETTING_CHANGED sheet=" + id + " by=" + user
                + " key=period-numbering-from value=" + (from == null ? "" : from));
        return saved;
    }

    /** Set the sheet's grace days (null: off), starting the sheet if it has never been loaded. Not dated. */
    @Transactional
    public Sheet setGraceDays(String id, String user, Integer graceDays) {
        load(id, user);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        sheet.setGraceDays(graceDays);
        Sheet saved = sheets.saveAndFlush(sheet);
        audit.recordChangeOnCommit(id, user, "SETTING_CHANGED sheet=" + id + " by=" + user
                + " key=grace-days value=" + (graceDays == null ? "" : graceDays));

/** Sheet endpoints. The caller's signed-in name comes in the {@code X-User} header. */
@RestController
@Validated
@RequestMapping("/api/sheets")
public class SheetController {

    /** A sheet as the screen shows it, each dated setting as it is in force on the sheet's today, with every dated value
     *  recorded; the clerk limit (null: no limit) and floor and late percent have exactly two decimals; terms is in days;
     *  the policy date is null when it is the sheet's today; the period numbering from is null when it is off; the cap (two decimals) is null when there is none, as are the proof threshold and the note threshold (two decimals); the permissions are the
     *  matrix entries set, by action (one missing keeps its standing rule); the grace days are null when off; archived is whether the sheet is archived;
     *  asOf is the date the sheet is shown as of, when it is (then the sheet is as it stood at the end of it, and today is that date), else null. */
    public record SheetView(String id, LocalDate today, String clerkLimit, String floor, int terms, String latePct,
            LocalDate policyDate, LocalDate periodNumberingFrom, Map<String, Integer> gradeTerms, String cap,
            List<DatedSettingView> settings, String proofThreshold, Map<String, String> permissions, Integer graceDays, boolean archived,
            LocalDate asOf, String noteThreshold) {

        static SheetView of(Sheet sheet) {
            return of(sheet, null);
        }

        static SheetView of(Sheet sheet, LocalDate asOf) {
            return new SheetView(sheet.getId(), sheet.getToday(),
                    sheet.getClerkLimit() == null ? null : sheet.getClerkLimit().toPlainString(),
                    sheet.getFloor().toPlainString(), sheet.getTerms(), sheet.getLatePct().toPlainString(), sheet.getPolicyDate(),
                    sheet.getPeriodNumberingFrom(), sheet.getGradeTerms(),
                    sheet.getCap() == null ? null : sheet.getCap().toPlainString(),
                    sheet.getSettings().stream().map(s -> new DatedSettingView(s.getKey(), s.getFrom(), s.getValue())).toList(),
                    sheet.getProofThreshold() == null ? null : sheet.getProofThreshold().toPlainString(),
                    sheet.getPermissions(), sheet.getGraceDays(), sheet.isArchived(), asOf,
                    sheet.getNoteThreshold() == null ? null : sheet.getNoteThreshold().toPlainString());
        }
    }

    /** A dated setting's value from a from-date (null: from the beginning of time); a null value means none. */
    public record DatedSettingView(String key, LocalDate from, String value) {
    }

    public record TodayChange(@NotNull LocalDate today) {
    }

    /** The sheet's settings as the form submits them; a missing clerk limit means no limit, a missing from-date the sheet's today. */
    public record SettingsChange(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal clerkLimit, LocalDate from) {
    }

    /** The sheet's floor as the form submits it. */
    public record FloorChange(@NotNull @DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal floor, LocalDate from) {
    }

    /** The sheet's terms, in days, as the form submits them. */
    public record TermsChange(@NotNull @Min(0) @Max(36500) Integer terms, LocalDate from) {
    }

    /** A grade's own terms, in days, as the form submits them; missing ones leave the grade on the sheet's terms. */
    public record GradeTermsChange(@Min(0) @Max(36500) Integer terms, LocalDate from) {
    }

    /** The sheet's late percent as the form submits it. */
    public record LatePctChange(@NotNull @DecimalMin("0.00") @Digits(integer = 3, fraction = 2) BigDecimal latePct, LocalDate from) {
    }

    /** The sheet's policy date as the form submits it; a missing one means the sheet's today. */
    public record PolicyDateChange(LocalDate policyDate) {
    }

    /** The sheet's period numbering from as the form submits it; a missing one means off. */
    public record PeriodNumberingFromChange(LocalDate periodNumberingFrom) {
    }

    /** The sheet's grace days as the form submits them; missing ones mean off. */
    public record GraceDaysChange(@Min(0) @Max(36500) Integer graceDays) {
    }

    /** The sheet's cap as the form submits it; a missing one means none. */
    public record CapChange(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal cap, LocalDate from) {
    }

    /** The sheet's proof threshold as the form submits it; a missing one means none. */
    public record ProofThresholdChange(@DecimalMin("0.00") @Digits(integer = 12, fraction = 2) BigDecimal proofThreshold, LocalDate from) {
    }

    }

    /** Change the sheet's late percent. */
    @PutMapping("/{id}/settings/late-pct")
    public SheetView setLatePct(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody LatePctChange request) {
        return SheetView.of(sheets.setLatePct(id, user, request.latePct(), request.from()));
    }

    /** Change the sheet's policy date. */
    @PutMapping("/{id}/settings/policy-date")
    public SheetView setPolicyDate(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PolicyDateChange request) {
        return SheetView.of(sheets.setPolicyDate(id, user, request.policyDate()));
    }

    /** Change the sheet's period numbering from. */
    @PutMapping("/{id}/settings/period-numbering-from")
    public SheetView setPeriodNumberingFrom(
            @PathVariable @NotBlank @Size(max = 100) @Pattern(regexp = "[A-Za-z0-9._-]+") String id,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PeriodNumberingFromChange request) {
package net.officefloor.hq.app.history;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeMap;
import net.officefloor.hq.app.claim.ClaimController.ClaimView;
import net.officefloor.hq.app.patron.PatronController.PatronView;
import net.officefloor.hq.app.period.PeriodController.PeriodView;
import net.officefloor.hq.app.person.PersonController.PersonView;
import net.officefloor.hq.app.rate.RateController.RateView;
import net.officefloor.hq.app.role.DelegationController.DelegationView;
import net.officefloor.hq.app.role.RoleController.RoleView;
import net.officefloor.hq.app.statement.StatementController.SummaryView;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.GradeFrom;
import net.officefloor.hq.app.person.Hold;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.sheet.Sheet;

/** What a sheet held at a moment. As far as a person's figures depend on it (its dated settings and policy date, its
 *  rates, its people and its claims) each part is rebuilt as an unsaved entity, so the figures of the sheet as it
 *  stood then are worked out by the same rules as the live ones. Alongside, the rest of what the screen shows of it,
 *  as the screen reads it: its other settings, and each list the screen reads (see {@link Views}). */
public record SheetState(List<SettingState> settings, LocalDate policyDate, List<RateState> rates,
        List<PersonState> people, List<ClaimState> claims, Map<String, String> permissions,
        LocalDate periodNumberingFrom, Integer graceDays, boolean archived, Views views) {

    /** Each list the screen reads of the sheet, as it read it then; a person's grade there is the one in force on the
     *  sheet's today then (see {@link #people(LocalDate)} for it on another day). */
    public record Views(List<PersonView> people, List<ClaimView> claims, List<RateView> rates,
            List<PeriodView> periods, List<SummaryView> statements, List<PatronView> patrons,
            Map<String, List<Long>> watches, List<RoleView> roles, List<DelegationView> delegations) {

        /** Nothing: a sheet as it stood before any change was made on it. */
        public static final Views NONE = new Views(List.of(), List.of(), List.of(), List.of(), List.of(), List.of(),
                Map.of(), List.of(), List.of());
    }

    public record SettingState(String key, LocalDate from, String value) {
    }

    public record RateState(String grade, LocalDate from, LocalDate to, BigDecimal rate) {
    }

    public record GradeState(LocalDate from, String grade) {
    }

    public record HoldState(LocalDate from, LocalDate to) {
    }

    public record PersonState(long id, String name, List<GradeState> grades, Integer terms, LocalDate retiredFrom,
            List<HoldState> holds) {

        /** The person as they stood then, unsaved. */
        public Person rebuild(String sheetId) {
            Person person = new Person(sheetId, name, grades.get(0).grade());
            grades.stream().skip(1).forEach(g -> person.setGradeFrom(g.from(), g.grade()));
            person.setTerms(terms);
            person.setRetiredFrom(retiredFrom);
            holds.forEach(h -> person.addHold(new Hold(h.from(), h.to())));
            return person;
        }
    }

    public record ClaimState(long id, long personId, BigDecimal amount, LocalDate date, LocalDate dueBy, String note,
            String corrects, long listed, ClaimStatus status, String number, BigDecimal settledDue, boolean stated,
            BigDecimal statedDue, LocalDate deferredUntil) {

        /** The claim as it stood then, unsaved. */
        public Claim rebuild(String sheetId) {
            Claim claim = new Claim(sheetId, personId, amount, date, dueBy, note, corrects, listed);
            claim.setStatus(status);
            claim.setNumber(number);
            claim.setSettledDue(settledDue);
            claim.setDeferredUntil(deferredUntil);
            if (stated) {
                claim.bind(statedDue);
            }
            return claim;
        }
    }

    /** What the sheet holds now. */
    public static SheetState of(Sheet sheet, List<Rate> rates, List<Person> people, List<Claim> claims, Views views) {
        return new SheetState(
                sheet.getSettings().stream().map(s -> new SettingState(s.getKey(), s.getFrom(), s.getValue())).toList(),
                sheet.getPolicyDate(),
                rates.stream().map(r -> new RateState(r.getGrade(), r.getFromDate(), r.getToDate(), r.getRate())).toList(),
                people.stream().map(SheetState::stateOf).toList(),
                claims.stream().map(c -> new ClaimState(c.getId(), c.getPersonId(), c.getAmount(), c.getDate(),
                        c.getDueBy(), c.getNote(), c.getCorrects(), c.getListed(), c.getStatus(), c.getNumber(),
                        c.getSettledDue(), c.isStated(), c.getStatedDue(), c.getDeferredUntil())).toList(),
                new TreeMap<>(sheet.getPermissions()), sheet.getPeriodNumberingFrom(), sheet.getGraceDays(),
                sheet.isArchived(), views);
    }

    /** The people as the screen read them then, each with the grade in force on {@code today}. */
    public List<PersonView> people(String sheetId, LocalDate today) {
        return views.people().stream().map(v -> person(v.id())
                .map(p -> new PersonView(v.id(), v.name(), p.rebuild(sheetId).gradeOn(today), v.grades(), v.terms(),
                        v.version(), v.retired(), v.retiredFrom(), v.held(), v.holds()))
                .orElse(v)).toList();
    }

    private static PersonState stateOf(Person p) {
        List<GradeFrom> grades = p.getGrades();
        return new PersonState(p.getId(), p.getName(),
                grades.stream().map(g -> new GradeState(g.getFromDate(), g.getGrade())).toList(), p.getTerms(),
                p.getRetiredFrom(), p.getHolds().stream().map(h -> new HoldState(h.getFromDate(), h.getToDate())).toList());
    }

    /** The sheet as it stood then, unsaved, with {@code today} standing in for its today. */
    public Sheet rebuildSheet(Sheet live, LocalDate today) {
        Sheet sheet = new Sheet(live.getId(), live.getCreatedBy(), live.getCreatedAt(), today);
        settings.forEach(s -> sheet.record(s.key(), s.from(), s.value()));
        sheet.setPolicyDate(policyDate);
        if (permissions != null) {
            permissions.forEach(sheet::setPermission);
        }
        sheet.setPeriodNumberingFrom(periodNumberingFrom);
        sheet.setGraceDays(graceDays);
        if (archived) {
            sheet.archive();
        }
        return sheet;
    }

    /** The rates as they stood then, unsaved. */
    public List<Rate> rebuildRates(String sheetId) {
        return rates.stream().map(r -> {
            Rate rate = new Rate(sheetId, r.grade(), r.from(), r.rate());
            rate.setToDate(r.to());
            return rate;
        }).toList();
    }

