    public SheetService(SheetRepository sheets, Rollup rollup, Audit audit, @Lazy PeriodService periods,
            ClaimRepository claims) {
        this.sheets = sheets;
        this.claims = claims;
        this.rollup = rollup;
        this.audit = audit;
        this.periods = periods;
    }

    /** The sheet with this id, re-read from the store; started empty if it has never been loaded. */
    @Transactional
    public Sheet load(String id, String user) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, user, Instant.now(), LocalDate.now()));
            } catch (DataIntegrityViolationException raced) {
                // Another user started the same sheet at the same moment: theirs stands.
                return sheets.findById(id).orElseThrow(() -> raced);
            }
        });
    }

    /** The sheet's today, or null for a sheet never loaded. */
    @Transactional(readOnly = true)
    public LocalDate today(String id) {
        return sheets.findById(id).map(Sheet::getToday).orElse(null);
    }

-- A sheet's history: after each change, what the sheet held (its dated settings, rates, people and claims, as JSON)
-- is kept under the sheet's today then; the latest kept under a day on or before a date is the sheet as it stood
-- at the end of that date, as a statement taken as of that date reads it.
CREATE TABLE sheet_snapshot (
    id       BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(100) NOT NULL REFERENCES sheet (id),
    as_of    DATE         NOT NULL,
    state    CLOB         NOT NULL
);
CREATE INDEX sheet_snapshot_as_of ON sheet_snapshot (sheet_id, as_of, id);
-- The sheet's grace days: when its today changes, every open period whose to-date plus these is before the new
-- today is closed. None means off. Not dated.
ALTER TABLE sheet ADD COLUMN grace_days INT;

